1	// Combines local provider pricing + Artificial Analysis benchmark data into
2	// per-category recommendations.
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	import { pricingSources } from "../pricing/sources.ts";
7	
8	// A PricingSource id, e.g. "copilot".
9	export type Provider = string;
10	
11	interface Candidate {
12	  provider: Provider;
13	  model: string;
14	  priceInput: number;
15	  priceOutput: number;
16	}
17	
18	export interface MappingEntry {
19	  provider: Provider;
20	  providerModel: string;
21	  aaSlug: string | null;
22	  note?: string;
23	}
24	
25	export interface AaModel {
26	  id: string;
27	  name: string;
28	  slug: string;
29	  evaluations: {
30	    artificial_analysis_intelligence_index?: number | null;
31	    artificial_analysis_coding_index?: number | null;
32	    artificial_analysis_agentic_index?: number | null;
33	  };
34	  performance?: {
35	    median_output_tokens_per_second?: number | null;
36	  };
37	}
38	
39	interface CategoryWeights {
40	  agenticIndex?: number;
41	  codingIndex?: number;
42	  intelligenceIndex?: number;
43	  costEfficiency?: number;
44	  speed?: number;
45	}
46	
47	interface BlacklistEntry {
48	  match: string;
49	  reason: string;
50	}
51	
52	interface ScoredCandidate {
53	  provider: Provider;
54	  model: string;
55	  aaSlug: string;
56	  score: number;
57	  breakdown: Record<string, number>;
58	  priceBlendedPer1M: number;
59	}
60	
61	const OUTPUT_OUTPUT_TO_INPUT_RATIO = 3; // assume 3 output tokens per 1 input token (typical agentic workload)
62	
63	function blendedPrice(priceInput: number, priceOutput: number): number {
64	  const totalParts = 1 + OUTPUT_OUTPUT_TO_INPUT_RATIO;
65	  return (priceInput * 1 + priceOutput * OUTPUT_OUTPUT_TO_INPUT_RATIO) / totalParts;
66	}
67	
68	// Strips variant qualifiers like " (<= 256K tokens)", " (Off-Peak)", " (Peak)" so
69	// tiered/peak pricing rows collapse to one representative candidate per base model.
70	export function baseModelName(model: string): string {
71	  let stripped = model;
72	  while (/\s*\([^)]*\)\s*$/.test(stripped)) {
73	    stripped = stripped.replace(/\s*\([^)]*\)\s*$/, "").trim();
74	  }
75	  return stripped;
76	}
77	
78	function dedupeCheapest(
79	  rows: { model: string; priceInput: number; priceOutput: number }[],
80	): { model: string; priceInput: number; priceOutput: number }[] {
81	  const byBase = new Map<string, { model: string; priceInput: number; priceOutput: number }>();
82	  for (const row of rows) {
83	    const base = baseModelName(row.model);
84	    const existing = byBase.get(base);
85	    if (
86	      !existing ||
87	      blendedPrice(row.priceInput, row.priceOutput) <
88	        blendedPrice(existing.priceInput, existing.priceOutput)
89	    ) {
90	      byBase.set(base, { model: base, priceInput: row.priceInput, priceOutput: row.priceOutput });
91	    }
92	  }
93	  return [...byBase.values()];
94	}
95	
96	export async function loadCandidates(): Promise<Candidate[]> {
97	  const candidates: Candidate[] = [];
98	  for (const source of pricingSources) {
99	    let raw: { models: Record<string, unknown>[] };
100	    try {
101	      raw = JSON.parse(await readFile(source.outFile, "utf8"));
102	    } catch (err) {
103	      // A provider whose parser has never succeeded has no data yet; score the others.
104	      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
105	      console.warn(
106	        `No ${source.displayName} pricing data at ${source.outFile}; skipping provider.`,
107	      );
108	      continue;
109	    }
110	
111	    const { input, output } = source.priceFields;
112	    const rows = dedupeCheapest(
113	      raw.models.map((m) => ({
114	        model: m.model as string,
115	        priceInput: m[input] as number,
116	        priceOutput: m[output] as number,
117	      })),
118	    );
119	    candidates.push(...rows.map((r) => ({ provider: source.id, ...r })));
120	  }
121	  return candidates;
122	}
123	
124	function normalize(value: number, min: number, max: number): number {
125	  if (max === min) return 1;
126	  return (value - min) / (max - min);
127	}
128	
129	export async function computeScores(): Promise<void> {
130	  const config = JSON.parse(await readFile(path.join("config", "categories.json"), "utf8"));
131	  const blacklist: BlacklistEntry[] = JSON.parse(
132	    await readFile(path.join("config", "blacklist.json"), "utf8"),
133	  );
